AssistantMessageToolRequest(name='create', tool_call_id='tooluse_2rhvNwyIqFzzkSMSJUWbzI', arguments={'file_text': 'const quizForm = document.getElementById('quizForm');
const resultContainer = document.getElementById('resultContainer');
const resultContent = document.getElementById('resultContent');

// Correct answers for each question
const correctAnswers = {
    q1: ['cpp', 'rust'],
    q2: ['javascript', 'php', 'ruby'],
    q3: ['python', 'javascript']
};

quizForm.addEventListener('submit', (e) => {
    e.preventDefault();

    const userAnswers = {
        q1: getSelectedAnswers('q1'),
        q2: getSelectedAnswers('q2'),
        q3: getSelectedAnswers('q3')
    };

    const results = evaluateAnswers(userAnswers);
    displayResults(results);
});

function getSelectedAnswers(questionName) {
    return Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`))
        .map(input => input.value);
}

function evaluateAnswers(userAnswers) {
    const results = [];
    let totalCorrect = 0;

    for (let i = 1; i <= 3; i++) {
        const question = `q${i}`;
        const correct = correctAnswers[question];
        const selected = userAnswers[question];

        // Check if the answers match exactly
        const isCorrect = arraysEqual(selected.sort(), correct.sort());

        results.push({
            question: i,
            isCorrect: isCorrect,
            selected: selected,
            correct: correct
        });

        if (isCorrect) totalCorrect++;
    }

    return {
        results: results,
        score: totalCorrect,
        total: 3
    };
}

function arraysEqual(arr1, arr2) {
    if (arr1.length !== arr2.length) return false;
    return arr1.every((val, idx) => val === arr2[idx]);
}

function displayResults(data) {
    quizForm.style.display = 'none';
    resultContainer.classList.remove('hidden');

    const scorePercentage = Math.round((data.score / data.total) * 100);
    let html = `<p style="font-size: 16px; margin-bottom: 16px;">
                    <strong>Your Score: ${data.score}/${data.total} (${scorePercentage}%)</strong>
                </p>`;

    data.results.forEach((result) => {
        const questionLabels = {
            1: 'compiled languages',
            2: 'web development languages',
            3: 'dynamically typed languages'
        };

        const questionText = questionLabels[result.question];
        const resultClass = result.isCorrect ? 'result-correct' : 'result-incorrect';
        const status = result.isCorrect ? '✓ Correct' : '✗ Incorrect';

        html += `<div class="result-item ${resultClass}">
                    <strong>Question ${result.question} (${questionText}):</strong><br>
                    ${status}<br>
                    <small>Your answer: ${result.selected.length > 0 ? result.selected.join(', ') : '(no selection)'}</small>
                </div>`;
    });

    resultContent.innerHTML = html;
}
