+const quizForm = document.getElementById('quizForm');
+const resultContainer = document.getElementById('resultContainer');
+const resultContent = document.getElementById('resultContent');
+
+// Correct answers for each question
+const correctAnswers = {
+    q1: ['cpp', 'rust'],
+    q2: ['javascript', 'php', 'ruby'],
+    q3: ['python', 'javascript']
+};
+
+quizForm.addEventListener('submit', (e) => {
+    e.preventDefault();
+    
+    const userAnswers = {
+        q1: getSelectedAnswers('q1'),
+        q2: getSelectedAnswers('q2'),
+        q3: getSelectedAnswers('q3')
+    };
+    
+    const results = evaluateAnswers(userAnswers);
+    displayResults(results);
+});
+
+function getSelectedAnswers(questionName) {
+    return Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`))
+        .map(input => input.value);
+}
+
+function evaluateAnswers(userAnswers) {
+    const results = [];
+    let totalCorrect = 0;
+    
+    for (let i = 1; i <= 3; i++) {
+        const question = `q${i}`;
+        const correct = correctAnswers[question];
+        const selected = userAnswers[question];
+        
+        // Check if the answers match exactly
+        const isCorrect = arraysEqual(selected.sort(), correct.sort());
+        
+        results.push({
+            question: i,
+            isCorrect: isCorrect,
+            selected: selected,
+            correct: correct
+        });
+        
+        if (isCorrect) totalCorrect++;
+    }
+    
+    return {
+        results: results,
+        score: totalCorrect,
